gbl(a){return"\u041f\u0430\u043c\u044b\u043b\u043a\u0430. \u041a\u0430\u043b\u0456 \u043b\u0430\u0441\u043a\u0430, \u043f\u0430\u0441\u043f\u0440\u0430\u0431\u0443\u0439\u0446\u0435 \u0437\u043d\u043e\u045e"},
gdR(){return"\u0417\u0430\u043f\u043e\u045e\u043d\u0456\u0446\u0435 \u045e\u0441\u0435 \u043f\u0430\u043b\u0456 \u043f\u0435\u0440\u0430\u0434 \u0430\u0434\u043f\u0440\u0430\u045e\u043a\u0430\u0439"},
