gey(){return"\u041a\u0430\u0440\u044b\u0441\u0442\u0430\u043b\u044c\u043d\u0456\u043a \u0456 \u043f\u0430\u0440\u043e\u043b\u044c"},
geB(){return"\u041d\u0430\u043f\u0456\u0448\u044b\u0446\u0435 \u043a\u0430\u0440\u044b\u0441\u0442\u0430\u043b\u044c\u043d\u0456\u043a\u0430 \u0442\u0443\u0442"},
ge2(){return"\u041d\u0430\u043f\u0456\u0448\u044b\u0446\u0435 \u043f\u0430\u0440\u043e\u043b\u044c \u0442\u0443\u0442"},
gdw(a){return"\u041f\u0430\u0446\u0432\u0435\u0440\u0434\u0437\u0456\u0446\u044c"},
geu(){return"\u041f\u0430\u0440\u043e\u043b\u044c \u0430\u0431\u043e \u0456\u043c\u044f \u043a\u0430\u0440\u044b\u0441\u0442\u0430\u043b\u044c\u043d\u0456\u043a\u0430 \u043d\u044f\u043f\u0440\u0430\u0432\u0456\u043b\u044c\u043d\u044b\u044f. \u041a\u0430\u043b\u0456 \u043b\u0430\u0441\u043a\u0430, \u0437\u0432\u044f\u0436\u044b\u0446\u0435\u0441\u044f \u0437 \u0432\u0430\u0448\u044b\u043c \u043a\u0456\u0440\u0430\u045e\u043d\u0456\u043a\u043e\u043c"},
geh(){return"\u041a\u0430\u043b\u0456 \u043b\u0430\u0441\u043a\u0430, \u0443\u0432\u044f\u0434\u0437\u0456\u0446\u0435 \u043f\u0440\u0430\u0432\u0456\u043b\u044c\u043d\u0430\u0435 \u0456\u043c\u044f \u043a\u0430\u0440\u044b\u0441\u0442\u0430\u043b\u044c\u043d\u0456\u043a\u0430 \u0456 \u043f\u0430\u0440\u043e\u043b\u044c"},
