gdG(){return"\u0421\u0430\u0440\u0442\u0430\u0432\u0430\u0446\u044c \u043f\u0430 \u043d\u0430\u0437\u0432\u0435"},
gdF(){return"\u0421\u0430\u0440\u0442\u0430\u0432\u0430\u0446\u044c \u043f\u0430 \u0430\u043f\u0456\u0441\u0430\u043d\u043d\u0456"},
ger(){return"\u0421\u0430\u0440\u0442\u0430\u0432\u0430\u0446\u044c \u043f\u0430 \u0456\u043c\u0435\u043d\u0456"},
ges(){return"\u0421\u0430\u0440\u0442\u0430\u0432\u0430\u0446\u044c \u043f\u0430 \u043f\u0430\u0441\u0430\u0434\u0437\u0435"},
gdD(){return"\u041d\u0456\u0447\u043e\u0433\u0430 \u043d\u0435 \u0437\u043d\u043e\u0439\u0434\u0437\u0435\u043d\u0430 \u045e \u0433\u044d\u0442\u044b\u043c \u0440\u0430\u0437\u0434\u0437\u0435\u043b\u0435"},
gcS(a){return"\u041f\u043e\u0448\u0443\u043a"},
gdZ(){return"\u0442\u0430\u043c\u0443"},
gea(){return"\u041f\u0430\u0434\u043a\u043b\u044e\u0447\u044b\u0446\u044c"},
gdz(){return"\u041f\u0430\u0434\u043a\u043b\u044e\u0447\u044d\u043d\u043d\u0435"},
gcG(){return"\u0431\u043e\u043b\u0435\u0439"},
gcF(){return"\u043c\u0435\u043d\u0448"},
gdY(){return"\u0423\u0434\u0437\u0435\u043b\u044c\u043d\u0456\u043a\u0456"},
